        ingredients=['1 1/4 lb (570 g) boneless skinless chicken thighs','1 teaspoon paprika','3/4 teaspoon salt, divided','1/4 teaspoon black pepper','1 tablespoon olive oil','1 small onion, finely diced','4 garlic cloves, minced','1 cup long-grain white rice, rinsed','1 3/4 cups low-sodium chicken broth','2 tablespoons butter','2 tablespoons chopped parsley'],
